 auto pGetDpiForWindow = (UINT(WINAPI*)(HWND))GetProcAddress(hUser32, "GetDpiForWindow");
 if (pGetDpiForWindow)
 m_dpi = (float)pGetDpiForWindow(m_hwnd);
 else
 m_dpi = 96.0f;
 }
 else
 m_dpi = 96.0f;

 // Создание фабрики D2D
 D2D1CreateFactory(D2D1_FACTORY_TYPE_SINGLE_THREADED,
 __uuidof(ID2D1Factory3),
 &m_d2dFactory);

 CreateIndependentResources();
 CreateDependentResources();

 // Регистрация и создание эффекта
 HabrEffect::Register(m_d2dFactory.Get());
 m_d2dContext->CreateEffect(HABR_EFFECT, m_HabrEffect.GetAddressOf());

 // Загрузка текстуры
 LoadTextureFromFile(L"image.png", blackBitmap);


 m_HabrEffect->SetInput(0, blackBitmap.Get());

 // Показываем окно
 ShowWindow(m_hwnd, nCmdShow);
 UpdateWindow(m_hwnd);

 return true;
}

// Создание независимых ресурсов (D3D11, связь с D2D)
void CreateIndependentResources()
{
 D3D11CreateDevice(
 nullptr,
 D3D_DRIVER_TYPE_HARDWARE,
 0,
 D3D11_CREATE_DEVICE_BGRA_SUPPORT,
 nullptr, 0,
 D3D11_SDK_VERSION,
 &device,
 &m_d3dFeatureLevel,
 &context
 );

 device.As(&dxgiDevice);
 m_d2dFactory->CreateDevice(dxgiDevice.Get(), &m_d2dDevice);
 m_d2dDevice->CreateDeviceContext(D2D1_DEVICE_CONTEXT_OPTIONS_NONE, &m_d2dContext);

 dxgiDevice->GetAdapter(&dxgiAdapter);
 dxgiAdapter->GetParent(IID_PPV_ARGS(&dxgiFactory));
}

// Создание зависимых ресурсов (цепочка обмена, целевой буфер)
void CreateDependentResources()
{
 m_d2dTargetBitmap.Reset();
 m_swapChain.Reset();

 DXGI_SWAP_CHAIN_DESC1 swapChainDesc = {};
 swapChainDesc.Width = static_cast<UINT>(m_d3dRenderTargetSize.width);
 swapChainDesc.Height = static_cast<UINT>(m_d3dRenderTargetSize.height);
 swapChainDesc.Format = DXGI_FORMAT_B8G8R8A8_UNORM;
 swapChainDesc.Stereo = FALSE;
 swapChainDesc.SampleDesc.Count = 1;
 swapChainDesc.SampleDesc.Quality = 0;
 swapChainDesc.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
 swapChainDesc.BufferCount = 2;
 swapChainDesc.SwapEffect = DXGI_SWAP_EFFECT_FLIP_SEQUENTIAL;
 swapChainDesc.Flags = 0;
 swapChainDesc.Scaling = DXGI_SCALING_NONE;
 swapChainDesc.AlphaMode = DXGI_ALPHA_MODE_IGNORE;

 dxgiFactory->CreateSwapChainForHwnd(
 device.Get(),
 m_hwnd,
 &swapChainDesc,
 nullptr,
 nullptr,
 &m_swapChain
 );

 dxgiDevice->SetMaximumFrameLatency(1);

 Microsoft::WRL::ComPtr<IDXGISurface2> dxgiBackBuffer;
 m_swapChain->GetBuffer(0, IID_PPV_ARGS(&dxgiBackBuffer));

 D2D1_BITMAP_PROPERTIES1 bitmapProperties =
 D2D1::BitmapProperties1(
 D2D1_BITMAP_OPTIONS_TARGET | D2D1_BITMAP_OPTIONS_CANNOT_DRAW,
 D2D1::PixelFormat(DXGI_FORMAT_B8G8R8A8_UNORM, D2D1_ALPHA_MODE_PREMULTIPLIED),
 m_dpi, m_dpi
 );

 m_d2dContext->CreateBitmapFromDxgiSurface(dxgiBackBuffer.Get(),
 &bitmapProperties, &m_d2dTargetBitmap);

 m_d2dContext->SetTarget(m_d2dTargetBitmap.Get());
}

// Загрузка текстуры из файла
HRESULT LoadTextureFromFile(const std::wstring& filename, Microsoft::WRL::ComPtr<ID2D1Bitmap1>& bitmap)
{
 Microsoft::WRL::ComPtr<IWICImagingFactory> wicFactory;
 HRESULT hr = CoCreateInstance(CLSID_WICImagingFactory, nullptr,
 CLSCTX_INPROC_SERVER, IID_PPV_ARGS(wicFactory.GetAddressOf()));
 if (FAILED(hr)) return hr;

 Microsoft::WRL::ComPtr<IWICBitmapDecoder> decoder;
 hr = wicFactory->CreateDecoderFromFilename(filename.c_str(), nullptr,
 GENERIC_READ, WICDecodeMetadataCacheOnLoad, decoder.GetAddressOf());
 if (FAILED(hr)) return hr;

 Microsoft::WRL::ComPtr<IWICBitmapFrameDecode> frame;
 hr = decoder->GetFrame(0, frame.GetAddressOf());
 if (FAILED(hr)) return hr;

 Microsoft::WRL::ComPtr<IWICFormatConverter> converter;
 hr = wicFactory->CreateFormatConverter(converter.GetAddressOf());
 if (FAILED(hr)) return hr;

 hr = converter->Initialize(frame.Get(), GUID_WICPixelFormat32bppPBGRA,
 WICBitmapDitherTypeNone, nullptr, 0.0f, WICBitmapPaletteTypeCustom);
 if (FAILED(hr)) return hr;

 return m_d2dContext->CreateBitmapFromWicBitmap(converter.Get(), nullptr, bitmap.GetAddressOf());
}

// Отрисовка одного кадра
void Render1()
{
 m_d2dContext->BeginDraw();

 m_d2dContext->Clear(D2D1::ColorF(D2D1::ColorF::CornflowerBlue));

 m_d2dContext->DrawImage(
 m_HabrEffect.Get(),
 D2D1_INTERPOLATION_MODE_LINEAR,
 D2D1_COMPOSITE_MODE_SOURCE_OVER
 );

 HRESULT hr = m_d2dContext->EndDraw();
 if (hr == D2DERR_RECREATE_TARGET)
 {
 OnResize();
 // Повторный вызов для перерисовки после восстановления
 Render1();
 return;
 }

 m_swapChain->Present(1, 0);
}

// Обработка изменения размера
void OnResize()
{
 if (m_hwnd)
 {
 RECT clientRect;
 GetClientRect(m_hwnd, &clientRect);
 m_d3dRenderTargetSize.width = static_cast<FLOAT>(clientRect.right - clientRect.left);
 m_d3dRenderTargetSize.height = static_cast<FLOAT>(clientRect.bottom - clientRect.top);

 if (m_swapChain)
 {
 m_d2dContext->SetTarget(nullptr);
 m_d2dTargetBitmap.Reset();

 if (m_d3dRenderTargetSize.width > 0 && m_d3dRenderTargetSize.height > 0)
 {
 m_swapChain->ResizeBuffers(0, 0, 0, DXGI_FORMAT_UNKNOWN, 0);
 CreateDependentResources();
 }
 }
 }
}

// Главный цикл
void Run()
{
 MSG msg = {};
 while (!m_windowClosed)
 {
 while (PeekMessage(&msg, nullptr, 0, 0, PM_REMOVE))
 {
 TranslateMessage(&msg);
 DispatchMessage(&msg);
 }

 // Рендерим каждый кадр
 if (!m_windowClosed)
 Render1();
 }
}

// Завершение работы
void Shutdown()
{
 m_windowClosed = true;

 // Освобождаем COM-объекты явно (хотя умные указатели сделают это сами)
 m_HabrEffect.Reset();
 blackBitmap.Reset();
 m_d2dTargetBitmap.Reset();
 m_d2dContext.Reset();
 m_d2dDevice.Reset();
 m_d2dFactory.Reset();
 m_swapChain.Reset();
 context.Reset();
 device.Reset();
 dxgiDevice.Reset();
 dxgiAdapter.Reset();
 dxgiFactory.Reset();

 if (m_hwnd)
 {
 DestroyWindow(m_hwnd);
 m_hwnd = nullptr;
 }
}

// Оконная процедура
LRESULT CALLBACK WndProc(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam)
{
 switch (message)
 {
 case WM_SIZE:
 if (wParam != SIZE_MINIMIZED)
 {
 OnResize();
 }
 return 0;

 case WM_DESTROY:
 m_windowClosed = true;
 PostQuitMessage(0);
 return 0;

 case WM_CLOSE:
 DestroyWindow(hWnd);
 return 0;
 }

 return DefWindowProc(hWnd, message, wParam, lParam);
}
